CREATE OR REPLACE FUNCTION legal_assert_coverage_registry_lineage()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $legal_coverage_registry_lineage$
DECLARE
    expected_registry_id TEXT;
    current_registry_id TEXT;
BEGIN
    NEW.registered_at := pg_catalog.statement_timestamp();
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            pg_catalog.concat_ws(
                E'\x1f',
                'legal-corpus-coverage-registry',
                NEW.provider_key,
                NEW.provider_revision::TEXT,
                NEW.coverage_contract_version
            ),
            0
        )
    );

    expected_registry_id :=
        'legal-corpus-coverage-registry:' ||
        encode(
            extensions.digest(
                convert_to(
                    concat_ws(
                        E'\n',
                        'legal-corpus-coverage-registry-v1',
                        NEW.provider_key,
                        NEW.provider_revision::TEXT,
                        NEW.registry_version,
                        NEW.coverage_contract_version
                    ),
                    'UTF8'
                ),
                'sha256'
            ),
            'hex'
        );
    IF NEW.coverage_registry_id <> expected_registry_id THEN
        RAISE EXCEPTION 'coverage registry id is not contract-derived'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_coverage_registry_derived_id';
    END IF;

    EXECUTE format(
        'SELECT registry.coverage_registry_id '
        'FROM %I.legal_corpus_coverage_registries AS registry '
        'WHERE registry.provider_key = $1 '
        'AND registry.provider_revision = $2 '
        'AND registry.coverage_contract_version = $3 '
        'AND NOT EXISTS ('
        '  SELECT 1 '
        '  FROM %I.legal_corpus_coverage_registries AS successor '
        '  WHERE successor.supersedes_coverage_registry_id = '
        '        registry.coverage_registry_id'
        ') '
        'ORDER BY registry.registered_at DESC '
        'LIMIT 1 FOR UPDATE OF registry',
        TG_TABLE_SCHEMA,
        TG_TABLE_SCHEMA
    )
    INTO current_registry_id
    USING
        NEW.provider_key,
        NEW.provider_revision,
        NEW.coverage_contract_version;

    IF current_registry_id IS NULL THEN
        IF NEW.supersedes_coverage_registry_id IS NOT NULL THEN
            RAISE EXCEPTION 'first coverage registry cannot supersede a row'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'ck_legal_coverage_registry_first';
        END IF;
    ELSIF NEW.supersedes_coverage_registry_id IS DISTINCT FROM
          current_registry_id THEN
        RAISE EXCEPTION 'coverage registry must supersede the current leaf'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_coverage_registry_lineage';
    END IF;
    RETURN NEW;
END;
$legal_coverage_registry_lineage$;
REVOKE ALL ON FUNCTION legal_assert_coverage_registry_lineage()
    FROM PUBLIC;

CREATE TRIGGER trg_legal_coverage_registry_lineage
    BEFORE INSERT ON legal_corpus_coverage_registries
    FOR EACH ROW
    EXECUTE FUNCTION legal_assert_coverage_registry_lineage();

CREATE OR REPLACE FUNCTION legal_assert_coverage_contract_identity()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $legal_coverage_contract_identity$
DECLARE
    registry_row RECORD;
    provider_id TEXT;
    expected_identity_sha256 TEXT;
    required_exists BOOLEAN;
BEGIN
    NEW.registered_at := pg_catalog.statement_timestamp();
    EXECUTE format(
        'SELECT provider_key, provider_revision, registry_version, '
        'coverage_contract_version '
        'FROM %I.legal_corpus_coverage_registries '
        'WHERE coverage_registry_id = $1',
        TG_TABLE_SCHEMA
    )
    INTO registry_row
    USING NEW.coverage_registry_id;
    IF registry_row IS NULL THEN
        RAISE EXCEPTION 'coverage registry is absent'
            USING ERRCODE = '23503';
    END IF;

    EXECUTE format(
        'SELECT EXISTS ('
        ' SELECT 1 '
        ' FROM %I.legal_corpus_required_target_contracts '
        ' WHERE provider_key = $1 '
        ' AND coverage_contract_version = $2 '
        ' AND resource_kind = $3 '
        ' AND provider_target = $4 '
        ' AND required'
        ')',
        TG_TABLE_SCHEMA
    )
    INTO required_exists
    USING
        registry_row.provider_key,
        registry_row.coverage_contract_version,
        NEW.resource_kind,
        NEW.provider_target;
    IF NOT COALESCE(required_exists, FALSE) THEN
        RAISE EXCEPTION 'coverage contract is not a required target'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_coverage_contract_required_target';
    END IF;

    provider_id :=
        'legal-provider:' ||
        encode(
            extensions.digest(
                convert_to(
                    format(
                        '{"providerKey":"%s","providerRevision":%s}',
                        registry_row.provider_key,
                        registry_row.provider_revision
                    ),
                    'UTF8'
                ),
                'sha256'
            ),
            'hex'
        );
    expected_identity_sha256 := encode(
        extensions.digest(
            convert_to(
                concat_ws(
                    E'\n',
                    'legal-corpus-coverage-v2',
                    provider_id,
                    registry_row.registry_version,
                    NEW.resource_kind,
                    NEW.provider_target,
                    NEW.query_sha256,
                    NEW.source_adapter_version,
                    NEW.boundary_contract_version,
                    registry_row.coverage_contract_version
                ),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
    IF NEW.coverage_identity_sha256 <> expected_identity_sha256
       OR NEW.coverage_contract_id <>
          'legal-corpus-coverage-contract:' || expected_identity_sha256 THEN
        RAISE EXCEPTION 'coverage contract identity is not deterministic'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_coverage_contract_derived_id';
    END IF;
    RETURN NEW;
END;
$legal_coverage_contract_identity$;
REVOKE ALL ON FUNCTION legal_assert_coverage_contract_identity()
    FROM PUBLIC;

CREATE TRIGGER trg_legal_coverage_contract_identity
    BEFORE INSERT ON legal_corpus_coverage_contracts
    FOR EACH ROW
    EXECUTE FUNCTION legal_assert_coverage_contract_identity();

CREATE OR REPLACE FUNCTION legal_assert_coverage_registry_complete()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $legal_coverage_registry_complete$
DECLARE
    registry_id TEXT;
    expected_count INTEGER;
    expected_hash TEXT;
    provider_key_value TEXT;
    contract_version_value TEXT;
    actual_count INTEGER;
    actual_hash TEXT;
    required_count INTEGER;
BEGIN
    registry_id := COALESCE(
        NEW.coverage_registry_id,
        NEW.coverage_registry_id
    );
    EXECUTE format(
        'SELECT expected_contract_count, expected_contracts_sha256, '
        'provider_key, coverage_contract_version '
        'FROM %I.legal_corpus_coverage_registries '
        'WHERE coverage_registry_id = $1',
        TG_TABLE_SCHEMA
    )
    INTO
        expected_count,
        expected_hash,
        provider_key_value,
        contract_version_value
    USING registry_id;
    IF expected_count IS NULL THEN
        RETURN NEW;
    END IF;

    EXECUTE format(
        'SELECT COUNT(*)::INTEGER, '
        'encode(extensions.digest(convert_to('
        '  string_agg(coverage_contract_id, E''\\n'' '
        '             ORDER BY coverage_contract_id), '
        '  ''UTF8'''
        '), ''sha256''), ''hex'') '
        'FROM %I.legal_corpus_coverage_contracts '
        'WHERE coverage_registry_id = $1',
        TG_TABLE_SCHEMA
    )
    INTO actual_count, actual_hash
    USING registry_id;
    EXECUTE format(
        'SELECT COUNT(*)::INTEGER '
        'FROM %I.legal_corpus_required_target_contracts '
        'WHERE provider_key = $1 '
        'AND coverage_contract_version = $2 '
        'AND required',
        TG_TABLE_SCHEMA
    )
    INTO required_count
    USING provider_key_value, contract_version_value;

    IF actual_count <> expected_count
       OR required_count <> expected_count
       OR actual_hash IS DISTINCT FROM expected_hash THEN
        RAISE EXCEPTION 'coverage registry member set is incomplete'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_coverage_registry_complete';
    END IF;
    RETURN NEW;
END;
$legal_coverage_registry_complete$;
REVOKE ALL ON FUNCTION legal_assert_coverage_registry_complete()
    FROM PUBLIC;

CREATE CONSTRAINT TRIGGER ctrg_legal_coverage_registry_complete
    AFTER INSERT ON legal_corpus_coverage_registries
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW
    EXECUTE FUNCTION legal_assert_coverage_registry_complete();
CREATE CONSTRAINT TRIGGER ctrg_legal_coverage_contract_registry_complete
    AFTER INSERT ON legal_corpus_coverage_contracts
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW
    EXECUTE FUNCTION legal_assert_coverage_registry_complete();

CREATE OR REPLACE FUNCTION legal_assert_coverage_bound_sync_run()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $legal_coverage_bound_sync_run$
DECLARE
    contract_row RECORD;
    provider_row RECORD;
    expected_scope_hash TEXT;
    identity_json JSONB;
BEGIN
    IF NEW.coverage_contract_id IS NULL THEN
        RETURN NEW;
    END IF;
    EXECUTE format(
        'SELECT contract.coverage_identity_sha256, '
        'contract.source_adapter_version, contract.resource_kind, '
        'contract.provider_target, contract.query_sha256, '
        'contract.boundary_contract_version, '
        'registry.coverage_registry_id, registry.provider_key, '
        'registry.provider_revision, registry.registry_version, '
        'registry.coverage_contract_version '
        'FROM %I.legal_corpus_coverage_contracts AS contract '
        'JOIN %I.legal_corpus_coverage_registries AS registry '
        'ON registry.coverage_registry_id = '
        '   contract.coverage_registry_id '
        'WHERE contract.coverage_contract_id = $1',
        TG_TABLE_SCHEMA,
        TG_TABLE_SCHEMA
    )
    INTO contract_row
    USING NEW.coverage_contract_id;
    EXECUTE format(
        'SELECT provider_key, provider_revision, adapter_version '
        'FROM %I.legal_source_providers '
        'WHERE provider_id = $1',
        TG_TABLE_SCHEMA
    )
    INTO provider_row
    USING NEW.provider_id;
    IF contract_row IS NULL
       OR provider_row IS NULL
       OR provider_row.provider_key <> contract_row.provider_key
       OR provider_row.provider_revision <> contract_row.provider_revision
       OR provider_row.adapter_version
          <> contract_row.source_adapter_version THEN
        RAISE EXCEPTION 'sync run is not bound to its provider contract'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_sync_run_coverage_provider';
    END IF;

    identity_json := NEW.metadata_json -> 'coverageIdentity';
    IF jsonb_typeof(identity_json) IS DISTINCT FROM 'object'
       OR identity_json ->> 'coverageContractId'
          IS DISTINCT FROM NEW.coverage_contract_id
       OR identity_json ->> 'coverageRegistryId'
          IS DISTINCT FROM contract_row.coverage_registry_id
       OR identity_json ->> 'coverageIdentitySha256'
          IS DISTINCT FROM contract_row.coverage_identity_sha256
       OR identity_json ->> 'resourceKind'
          IS DISTINCT FROM contract_row.resource_kind
       OR identity_json ->> 'target'
          IS DISTINCT FROM contract_row.provider_target
       OR identity_json ->> 'querySha256'
          IS DISTINCT FROM contract_row.query_sha256
       OR identity_json ->> 'sourceAdapterVersion'
          IS DISTINCT FROM contract_row.source_adapter_version
       OR identity_json ->> 'boundaryContractVersion'
          IS DISTINCT FROM contract_row.boundary_contract_version
       OR identity_json ->> 'registryVersion'
          IS DISTINCT FROM contract_row.registry_version
       OR identity_json ->> 'coverageContractVersion'
          IS DISTINCT FROM contract_row.coverage_contract_version THEN
        RAISE EXCEPTION 'sync run typed coverage identity is inconsistent'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_sync_run_coverage_identity';
    END IF;

    expected_scope_hash := encode(
        extensions.digest(
            convert_to(
                concat_ws(
                    E'\n',
                    'legal-corpus-scope-v1',
                    octet_length(NEW.provider_id)::TEXT
                        || ':' || NEW.provider_id,
                    octet_length(
                        contract_row.coverage_identity_sha256
                    )::TEXT || ':'
                        || contract_row.coverage_identity_sha256,
                    octet_length(btrim(NEW.requested_scope))::TEXT
                        || ':' || btrim(NEW.requested_scope)
                ),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
    IF NEW.requested_scope <> btrim(NEW.requested_scope)
       OR NEW.requested_scope_hash <> expected_scope_hash THEN
        RAISE EXCEPTION 'sync run coverage scope hash is inconsistent'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_sync_run_coverage_scope';
    END IF;
    RETURN NEW;
END;
$legal_coverage_bound_sync_run$;
REVOKE ALL ON FUNCTION legal_assert_coverage_bound_sync_run()
    FROM PUBLIC;

CREATE TRIGGER trg_legal_coverage_bound_sync_run
    BEFORE INSERT ON legal_sync_runs
    FOR EACH ROW
    EXECUTE FUNCTION legal_assert_coverage_bound_sync_run();

CREATE OR REPLACE FUNCTION legal_assert_coverage_bound_completion()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $legal_coverage_bound_completion$
DECLARE
    contract_identity_sha256 TEXT;
    expected_scope_hash TEXT;
    matching_checkpoint_count INTEGER;
    baseline_row RECORD;
    current_leaf_id TEXT;
BEGIN
    IF NEW.coverage_contract_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF NEW.verification_status <> 'verified' THEN
        RAISE EXCEPTION
            'coverage-bound completion must be verified'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_completion_coverage_verified';
    END IF;
    EXECUTE format(
        'SELECT coverage_identity_sha256 '
        'FROM %I.legal_corpus_coverage_contracts '
        'WHERE coverage_contract_id = $1',
        TG_TABLE_SCHEMA
    )
    INTO contract_identity_sha256
    USING NEW.coverage_contract_id;
    IF contract_identity_sha256 IS NULL THEN
        RAISE EXCEPTION 'completion coverage contract is absent'
            USING ERRCODE = '23503';
    END IF;
    expected_scope_hash := encode(
        extensions.digest(
            convert_to(
                concat_ws(
                    E'\n',
                    'legal-corpus-scope-v1',
                    octet_length(NEW.provider_id)::TEXT
                        || ':' || NEW.provider_id,
                    octet_length(contract_identity_sha256)::TEXT
                        || ':' || contract_identity_sha256,
                    octet_length(btrim(NEW.requested_scope))::TEXT
                        || ':' || btrim(NEW.requested_scope)
                ),
                'UTF8'
            ),
            'sha256'
        ),
        'hex'
    );
    IF NEW.requested_scope <> btrim(NEW.requested_scope)
       OR NEW.requested_scope_hash <> expected_scope_hash THEN
        RAISE EXCEPTION 'completion coverage scope hash is inconsistent'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_completion_coverage_scope';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            pg_catalog.concat_ws(
                E'\x1f',
                'legal-corpus-coverage-completion',
                NEW.provider_id,
                NEW.requested_scope_hash,
                NEW.coverage_contract_id
            ),
            0
        )
    );

    IF NEW.page_count <>
       NEW.last_checkpoint_sequence - NEW.first_checkpoint_sequence + 1 THEN
        RAISE EXCEPTION
            'completion checkpoint sequence range must be contiguous'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_completion_coverage_contiguous';
    END IF;

    EXECUTE format(
        'SELECT COUNT(*)::INTEGER '
        'FROM %I.legal_sync_checkpoint_events AS checkpoint '
        'JOIN %I.legal_sync_runs AS run '
        'ON run.sync_run_id = checkpoint.sync_run_id '
        'AND run.provider_id = checkpoint.provider_id '
        'WHERE checkpoint.provider_id = $1 '
        'AND checkpoint.requested_scope_hash = $2 '
        'AND checkpoint.checkpoint_sequence BETWEEN $3 AND $4 '
        'AND run.coverage_contract_id = $5',
        TG_TABLE_SCHEMA,
        TG_TABLE_SCHEMA
    )
    INTO matching_checkpoint_count
    USING
        NEW.provider_id,
        NEW.requested_scope_hash,
        NEW.first_checkpoint_sequence,
        NEW.last_checkpoint_sequence,
        NEW.coverage_contract_id;
    IF matching_checkpoint_count <> NEW.page_count THEN
        RAISE EXCEPTION 'completion includes another coverage contract run'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_completion_coverage_runs';
    END IF;

    EXECUTE format(
        'SELECT completion.completion_attestation_id '
        'FROM %1$I.legal_corpus_scope_completion_attestations '
        '     AS completion '
        'WHERE completion.provider_id = $1 '
        'AND completion.requested_scope_hash = $2 '
        'AND completion.coverage_contract_id = $3 '
        'AND NOT EXISTS ('
        '  SELECT 1 '
        '  FROM %1$I.legal_corpus_scope_completion_attestations '
        '       AS successor '
        '  WHERE successor.baseline_completion_attestation_id = '
        '        completion.completion_attestation_id'
        ') '
        'ORDER BY completion.last_checkpoint_sequence DESC '
        'LIMIT 1 FOR UPDATE OF completion',
        TG_TABLE_SCHEMA
    )
    INTO current_leaf_id
    USING
        NEW.provider_id,
        NEW.requested_scope_hash,
        NEW.coverage_contract_id;

    IF NEW.coverage_mode = 'initial' THEN
        IF NEW.first_checkpoint_sequence <> 1
           OR NEW.baseline_completion_attestation_id IS NOT NULL
           OR current_leaf_id IS NOT NULL THEN
            RAISE EXCEPTION 'initial completion must start at sequence one'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'ck_legal_completion_initial_baseline';
        END IF;
    ELSIF NEW.coverage_mode = 'incremental' THEN
        EXECUTE format(
            'SELECT provider_id, requested_scope_hash, '
            'coverage_contract_id, coverage_mode, '
            'last_checkpoint_sequence, verification_status '
            'FROM %I.legal_corpus_scope_completion_attestations '
            'WHERE completion_attestation_id = $1',
            TG_TABLE_SCHEMA
        )
        INTO baseline_row
        USING NEW.baseline_completion_attestation_id;
        IF baseline_row IS NULL
           OR baseline_row.provider_id <> NEW.provider_id
           OR baseline_row.requested_scope_hash
              <> NEW.requested_scope_hash
           OR baseline_row.coverage_contract_id
              <> NEW.coverage_contract_id
           OR baseline_row.coverage_mode
              NOT IN ('initial', 'incremental')
           OR baseline_row.verification_status <> 'verified'
           OR NEW.baseline_completion_attestation_id
              IS DISTINCT FROM current_leaf_id
           OR baseline_row.last_checkpoint_sequence + 1
              <> NEW.first_checkpoint_sequence THEN
            RAISE EXCEPTION 'incremental completion baseline is invalid'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'ck_legal_completion_incremental_baseline';
        END IF;
    ELSE
        RAISE EXCEPTION 'completion coverage mode is invalid'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'ck_legal_completion_coverage_binding';
    END IF;
    RETURN NEW;
END;
$legal_coverage_bound_completion$;
REVOKE ALL ON FUNCTION legal_assert_coverage_bound_completion()
    FROM PUBLIC;

CREATE TRIGGER trg_legal_coverage_bound_completion
    BEFORE INSERT ON legal_corpus_scope_completion_attestations
    FOR EACH ROW
    EXECUTE FUNCTION legal_assert_coverage_bound_completion();

